// Two failure shapes, not one:
//  - the heartbeat row is STALE  -> the pipeline stopped succeeding;
//  - the heartbeat row is MISSING -> it never ran at all, which is the case
//    people forget to handle and the one that hides longest.
// A threshold that ignores business hours cries wolf every night, so the
// quiet window is widened outside working hours instead of being disabled.
const rows = items.filter(i => i.json && i.json.last_success);
const hour = new Date().getUTCHours();
const businessHours = hour >= 6 && hour < 19;
const limit = businessHours ? 45 : 240;

if (rows.length === 0) {
  return [{ json: {
    alarm: true,
    silent_minutes: null,
    limit_minutes: limit,
    reason: 'no heartbeat row at all - the intake has never completed a run'
  } }];
}

const silent = Math.round(Number(rows[0].json.silent_minutes));
return [{ json: {
  alarm: silent > limit,
  silent_minutes: silent,
  limit_minutes: limit,
  last_success: rows[0].json.last_success,
  reason: silent > limit
    ? `no successful run for ${silent} min (limit ${limit})`
    : 'healthy'
} }];
